"""MVTec AD, VisA and MVTec AD 2 readers with a common sample format.

Expected layouts (``root`` = ``<data_root>/<dataset name>``):

* MVTec AD:   <cls>/train/good/*.png, <cls>/test/<defect>/*.png, <cls>/ground_truth/<defect>/<stem>_mask.png
* VisA:       the official release with ``split_csv/1cls.csv`` (columns object, split, label, image, mask)
* MVTec AD 2: <cls>/train/good, <cls>/validation/good, <cls>/test_public/{good,bad},
              <cls>/test_public/ground_truth/bad/<stem>_mask.png
* toy:        same layout as MVTec AD (generated by ``fscad.data.toy``)
"""

from __future__ import annotations

import csv
from dataclasses import dataclass
from pathlib import Path

import numpy as np
import torch
from PIL import Image
from torch.utils.data import Dataset

IMAGENET_MEAN = (0.485, 0.456, 0.406)
IMAGENET_STD = (0.229, 0.224, 0.225)
IMG_EXTS = {".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff"}

MVTEC_AD_CLASSES = [
    "bottle",
    "cable",
    "capsule",
    "carpet",
    "grid",
    "hazelnut",
    "leather",
    "metal_nut",
    "pill",
    "screw",
    "tile",
    "toothbrush",
    "transistor",
    "wood",
    "zipper",
]
VISA_CLASSES = [
    "candle",
    "capsules",
    "cashew",
    "chewinggum",
    "fryum",
    "macaroni1",
    "macaroni2",
    "pcb1",
    "pcb2",
    "pcb3",
    "pcb4",
    "pipe_fryum",
]
MVTEC_AD2_CLASSES = [
    "can",
    "fabric",
    "fruit_jelly",
    "rice",
    "sheet_metal",
    "vial",
    "wallplugs",
    "walnuts",
]
TEXTURE_CLASSES = {"carpet", "grid", "leather", "tile", "wood", "fabric"}


@dataclass(frozen=True)
class Sample:
    path: str
    label: int  # 0 normal, 1 anomalous
    mask: str | None
    cls: str
    defect: str = "good"


def dataset_classes(name: str, root: str | Path | None = None) -> list[str]:
    if name == "mvtec_ad":
        return list(MVTEC_AD_CLASSES)
    if name == "visa":
        return list(VISA_CLASSES)
    if name == "mvtec_ad2":
        return list(MVTEC_AD2_CLASSES)
    if root is not None and Path(root).exists():  # toy / custom MVTec-style folder
        return sorted(p.name for p in Path(root).iterdir() if (p / "train").is_dir())
    raise ValueError(f"unknown dataset {name!r}")


def _images(folder: Path) -> list[Path]:
    if not folder.is_dir():
        return []
    return sorted(p for p in folder.iterdir() if p.suffix.lower() in IMG_EXTS)


def _find_mask(gt_dir: Path, stem: str) -> str | None:
    for cand in (gt_dir / f"{stem}_mask.png", gt_dir / f"{stem}.png"):
        if cand.exists():
            return str(cand)
    hits = sorted(gt_dir.glob(f"{stem}*")) if gt_dir.is_dir() else []
    return str(hits[0]) if hits else None


def _mvtec_style(
    root: Path,
    cls: str,
    split: str,
    train_dir: str = "train",
    test_dir: str = "test",
    gt_dir: str = "ground_truth",
) -> list[Sample]:
    base = root / cls
    if split in ("train", "validation"):
        folder = base / (train_dir if split == "train" else "validation") / "good"
        return [Sample(str(p), 0, None, cls) for p in _images(folder)]
    out: list[Sample] = []
    test_root = base / test_dir
    if not test_root.is_dir():
        raise FileNotFoundError(test_root)
    gt_root = test_root / gt_dir if (test_root / gt_dir).is_dir() else base / gt_dir
    for defect_dir in sorted(p for p in test_root.iterdir() if p.is_dir() and p.name != gt_dir):
        defect = defect_dir.name
        for img in _images(defect_dir):
            if defect == "good":
                out.append(Sample(str(img), 0, None, cls, defect))
            else:
                out.append(Sample(str(img), 1, _find_mask(gt_root / defect, img.stem), cls, defect))
    return out


def _visa(root: Path, cls: str, split: str) -> list[Sample]:
    csv_path = root / "split_csv" / "1cls.csv"
    if not csv_path.exists():  # already converted to MVTec layout (e.g. by anomalib)
        return _mvtec_style(root, cls, split)
    want = "train" if split in ("train", "validation") else "test"
    out = []
    with open(csv_path, newline="") as f:
        for row in csv.DictReader(f):
            if row["object"] != cls or row["split"] != want:
                continue
            label = 0 if row["label"] == "normal" else 1
            mask = str(root / row["mask"]) if label and row.get("mask") else None
            out.append(
                Sample(str(root / row["image"]), label, mask, cls, "good" if label == 0 else "anomaly")
            )
    return out


def list_samples(dataset: str, root: str | Path, cls: str, split: str) -> list[Sample]:
    """split: 'train' | 'validation' | 'test'."""
    root = Path(root)
    if dataset == "visa":
        return _visa(root, cls, split)
    if dataset == "mvtec_ad2":
        return _mvtec_style(root, cls, split, test_dir="test_public")
    return _mvtec_style(root, cls, split)


def load_image(path: str | Path, size: int) -> torch.Tensor:
    """RGB image in [0, 1], shape (3, size, size)."""
    img = Image.open(path).convert("RGB").resize((size, size), Image.BICUBIC)
    return torch.from_numpy(np.asarray(img, dtype=np.float32) / 255.0).permute(2, 0, 1)


def load_mask(path: str | None, size: int) -> torch.Tensor:
    if path is None:
        return torch.zeros(size, size)
    m = Image.open(path).convert("L").resize((size, size), Image.NEAREST)
    return torch.from_numpy((np.asarray(m) > 127).astype(np.float32))


def normalize(x: torch.Tensor) -> torch.Tensor:
    mean = torch.tensor(IMAGENET_MEAN, device=x.device).view(-1, 1, 1)
    std = torch.tensor(IMAGENET_STD, device=x.device).view(-1, 1, 1)
    return (x - mean) / std


class ADDataset(Dataset):
    """Returns raw images in [0, 1]; normalisation happens on device right before the backbone."""

    def __init__(self, samples: list[Sample], img_size: int, mask_size: int):
        self.samples = samples
        self.img_size = img_size
        self.mask_size = mask_size

    def __len__(self) -> int:
        return len(self.samples)

    def __getitem__(self, i: int) -> dict:
        s = self.samples[i]
        return {
            "image": load_image(s.path, self.img_size),
            "mask": load_mask(s.mask, self.mask_size),
            "label": s.label,
            "path": s.path,
            "cls": s.cls,
        }
